from pathlib import Path
import sys,re
src=Path(sys.argv[1]).read_text();src=src.replace('// 参考: https://zenn.dev/reputeless/books/standard-cpp-for-competitive-programming/viewer/lis','// Original Source: https://zenn.dev/reputeless/books/standard-cpp-for-competitive-programming/viewer/lis')
for header in ['cmath','stdexcept','type_traits']:
 if '#include <'+header+'>'not in src:src=src.replace('#include <algorithm>','#include <algorithm>\n#include <'+header+'>')
helper='''#ifndef SKIP_RUNTIME_CHECKS
#ifndef SIRKIT_LIS_INPUT_CHECK_DEFINED
#define SIRKIT_LIS_INPUT_CHECK_DEFINED
namespace reinsirk::detail {
template <class T>
void check_lis_value(const T& value) {
    if constexpr (std::is_floating_point_v<T>)
        if (std::isnan(value)) throw std::invalid_argument("LIS: NaN input");
}
} // namespace reinsirk::detail
#endif
#endif

'''
pos=src.index('#ifndef SIRKIT_LIS_LENGTHS_DEFINED');src=src[:pos]+helper+src[pos:]
assert 'for (const auto& value : v) {'in src
src=src.replace('for (const auto& value : v) {','for (const auto& value : v) {\n#ifndef SKIP_RUNTIME_CHECKS\n        reinsirk::detail::check_lis_value(value);\n#endif')
pattern=r'(for \(std::size_t i = 0; i < v\.size\(\); \+\+i\) \{)'
src,count=re.subn(pattern,r'\1\n#ifndef SKIP_RUNTIME_CHECKS\n        reinsirk::detail::check_lis_value(v[i]);\n#endif',src);assert count>=1
src+='''
#ifndef SIRKIT_LIS_ENDING_LENGTHS_DEFINED
#define SIRKIT_LIS_ENDING_LENGTHS_DEFINED
// LISEndingLengths<Strict=true>(v): 各要素を末尾とする最長長。狭義/広義、空なら空、O(N log(L+1))時間・O(N+L)領域。
// 全APIの比較はoperator<の狭義弱順序が前提。浮動NaNは検査時に拒否し、±infは許可する。
template <bool Strict = true, class T>
std::vector<std::size_t> LISEndingLengths(const std::vector<T>& v) {
    std::vector<T> tails;
    tails.reserve(std::min(v.size(), std::size_t{64}));
    std::vector<std::size_t> result;
    result.reserve(v.size());
    for (const auto& value : v) {
#ifndef SKIP_RUNTIME_CHECKS
        reinsirk::detail::check_lis_value(value);
#endif
        if (tails.empty() || (Strict ? tails.back() < value : !(value < tails.back()))) {
            tails.push_back(value);
            result.push_back(tails.size());
        } else {
            auto it = Strict ? std::lower_bound(tails.begin(), tails.end(), value)
                             : std::upper_bound(tails.begin(), tails.end(), value);
            const auto length = static_cast<std::size_t>(it - tails.begin()) + 1;
            *it = value;
            result.push_back(length);
        }
    }
    return result;
}
#endif
'''
# NaN検査の範囲と必要な型操作をAPI説明にまとめる。
src=src.replace('// LIS<Strict>(v):','// 比較はoperator<の狭義弱順序。浮動NaNは検査時に拒否、±infは許可。\n// LIS/Length/EndingLengthsはTのコピー構築・代入、Sequenceはコピー構築が必要。\n// LIS<Strict>(v):',1)
src=src.replace('// LISIndices<Strict=true>(v):','// LISIndicesはconst Tの比較だけを使い、コピー不能・非default構築の型も扱う。\n// LISIndices<Strict=true>(v):',1)
Path(sys.argv[2]).write_text(src)

