#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <vector>
struct Node{std::size_t length=0,index=0;};
int main(){
 std::size_t n{};if(!(std::cin>>n))return 0;std::vector<std::int64_t>a(n);for(auto&v:a)std::cin>>v;
 auto coords=a;std::sort(coords.begin(),coords.end());coords.erase(std::unique(coords.begin(),coords.end()),coords.end());
 const auto none=n;std::vector<Node> tree(coords.size()+1);std::vector<std::size_t>prev(n,none);Node best{};
 for(std::size_t i=0;i<n;++i){
  const auto pos=static_cast<std::size_t>(std::lower_bound(coords.begin(),coords.end(),a[i])-coords.begin());Node current{};
  for(auto j=pos;j;j-=j&(~j+1))if(tree[j].length>current.length)current=tree[j];
  if(current.length)prev[i]=current.index;const Node update{current.length+1,i};
  for(auto j=pos+1;j<tree.size();j+=j&(~j+1))if(update.length>tree[j].length)tree[j]=update;
  if(update.length>best.length)best=update;
 }
 std::vector<std::size_t>ans(best.length);auto index=best.index;
 for(std::size_t left=ans.size();left;--left){ans[left-1]=index;index=prev[index];}
 std::cout<<ans.size()<<'\n';for(auto i:ans)std::cout<<i<<' ';std::cout<<'\n';
}

