#include SIRKIT_LIS_SOURCE
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <vector>
template<bool Strict>void check(const std::vector<int>& v){
 const auto ids=LISIndices<Strict>(v);std::vector<std::size_t> dp(v.size(),1);std::size_t best=0;
 for(std::size_t i=0;i<v.size();++i){for(std::size_t j=0;j<i;++j)if(Strict?v[j]<v[i]:!(v[i]<v[j]))dp[i]=std::max(dp[i],dp[j]+1);best=std::max(best,dp[i]);}
 assert(ids.size()==best);for(std::size_t j=0;j<ids.size();++j){assert(ids[j]<v.size());if(j)assert(ids[j-1]<ids[j]&&(Strict?v[ids[j-1]]<v[ids[j]]:!(v[ids[j]]<v[ids[j-1]])));}
}
int main(){std::uint64_t state=821793;
 for(int n=0;n<=258;++n){std::vector<int> v(n);for(int mode=0;mode<5;++mode){for(int i=0;i<n;++i){state=state*UINT64_C(6364136223846793005)+1;v[i]=mode==0?i:mode==1?-i:mode==2?0:mode==3?(i%2?i:-i):static_cast<int>((state>>32)%101)-50;}check<true>(v);check<false>(v);}}
 std::puts("PASS MemorySanitizer predecessor chains");}

