#include HEADER
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <string>
#include <vector>
using I=std::int64_t;
static void barrier(){std::atomic_signal_fence(std::memory_order_seq_cst);}
template<bool Strict>[[gnu::noinline]]static std::vector<std::size_t> calculate(const std::vector<I>& a){barrier();auto r=LISIndices<Strict>(a);barrier();return r;}
static std::vector<I> make(const std::string&shape,int n){std::mt19937_64 rng(91273);std::vector<I>a(n);for(int i=0;i<n;++i){if(shape=="ascending")a[i]=i;else if(shape=="descending")a[i]=n-i;else if(shape=="equal")a[i]=17;else if(shape=="duplicates")a[i]=I(rng()%128);else if(shape=="zigzag")a[i]=(i&1)?i:-i;else a[i]=I(rng()%1000000001);}return a;}
int main(){for(const auto*shape:{"small","random","ascending","descending","equal","duplicates","zigzag"}){auto a=make(shape,std::string(shape)=="small"?32:500000);for(bool strict:{true,false}){auto t=std::chrono::steady_clock::now();const auto r=strict?calculate<true>(a):calculate<false>(a);auto ns=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-t).count();for(std::size_t i=0;i<r.size();++i)if(r[i]>=a.size()||(i&&(r[i-1]>=r[i]||(strict?!(a[r[i-1]]<a[r[i]]):a[r[i]]<a[r[i-1]]))))std::abort();std::printf("%s:%d %.9f %zu\n",shape,int(strict),ns/a.size(),r.size());}}}

opt/final_api/bench.cpp.source:
#include HEADER
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <map>
#include <random>
#include <string>
#include <type_traits>
#include <vector>
struct Item {std::int64_t value;explicit Item(std::int64_t x):value(x){}friend bool operator<(const Item&a,const Item&b){return a.value<b.value;}};
template<class T>static std::int64_t numeric(const T&x){if constexpr(std::is_same_v<T,Item>)return x.value;else return static_cast<std::int64_t>(x);}
static void barrier(){std::atomic_signal_fence(std::memory_order_seq_cst);}
template<bool Strict,bool Sequence,class T>[[gnu::noinline]]static auto calculate(const std::vector<T>&a){barrier();if constexpr(Sequence){auto r=LISSequence<Strict>(a);barrier();return r;}else{auto r=LISIndices<Strict>(a);barrier();return r;}}
template<class T>static std::vector<T> prepare(const std::string&shape){const int n=shape=="small"?32:20000;std::mt19937_64 rng(125091);std::vector<T>a;a.reserve(n);for(int i=0;i<n;++i){std::int64_t x;if(shape=="ascending")x=i;else if(shape=="descending")x=n-i;else if(shape=="equal")x=17;else if(shape=="duplicates")x=static_cast<std::int64_t>(rng()%128);else if(shape=="zigzag")x=(i&1)?i:-i;else x=static_cast<std::int64_t>(rng()%1000000001);a.emplace_back(static_cast<T>(x));}return a;}
template<bool Strict,bool Sequence,class T>static void measure(const std::string&type,const std::string&shape,const std::vector<T>&a,const std::map<std::string,std::size_t>&batches,bool check){
 const std::string key=type+":"+shape+":"+(Strict?"strict":"weak")+":"+(Sequence?"sequence":"indices");
 if(check){const auto r=calculate<Strict,Sequence>(a);const auto ii=LISIndices<Strict>(a);const auto best=LISLength<Strict>(a);if(ii.size()!=best||r.size()!=best)std::abort();for(std::size_t j=0;j<ii.size();++j){if(ii[j]>=a.size()||(j&&(ii[j-1]>=ii[j]||(Strict?!(a[ii[j-1]]<a[ii[j]]):a[ii[j]]<a[ii[j-1]]))))std::abort();if constexpr(Sequence){if(numeric(r[j])!=numeric(a[ii[j]]))std::abort();} }std::printf("checked %s %zu\n",key.c_str(),best);return;}
 const auto it=batches.find(key);const std::size_t count=it==batches.end()?1:it->second;std::uint64_t checksum=0;barrier();const auto start=std::chrono::steady_clock::now();
 for(std::size_t repeat=0;repeat<count;++repeat){const auto result=calculate<Strict,Sequence>(a);checksum+=result.size();if(!result.empty()){checksum+=static_cast<std::uint64_t>(numeric(result.front()));checksum+=static_cast<std::uint64_t>(numeric(result.back()));}}
 barrier();const auto elapsed=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-start).count();std::printf("%s %.9f %zu %ju\n",key.c_str(),elapsed/count,count,static_cast<std::uintmax_t>(checksum));
}
template<class T>static void process(const char*type,const std::vector<std::string>&shapes,const std::map<std::string,std::size_t>&batches,bool check){for(const auto&shape:shapes){const auto a=prepare<T>(shape);measure<true,false>(type,shape,a,batches,check);measure<false,false>(type,shape,a,batches,check);measure<true,true>(type,shape,a,batches,check);measure<false,true>(type,shape,a,batches,check);}}
int main(int argc,char**argv){const bool check=argc>1&&std::string(argv[1])=="check";std::map<std::string,std::size_t>batches;if(argc>2){std::ifstream input(argv[2]);std::string key;std::size_t n;while(input>>key>>n)batches[key]=n;}process<std::int64_t>("int64",{"small","random","ascending","descending","equal","duplicates","zigzag"},batches,check);process<double>("double",{"random","equal"},batches,check);process<Item>("generic",{"random","equal"},batches,check);}

